import{_ as i,c as t,o as a,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"Achieving Efficiency Through State and Local Preparedness","description":"","frontmatter":{"title":"Achieving Efficiency Through State and Local Preparedness","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/achieving-efficiency-through-state-and-local-preparedness/","publishDate":"2025-03-19T10:20:57-04:00"},"headers":[],"relativePath":"executive-orders/2025-03-19-achieving-efficiency-through-state-and-local-preparedness.md","filePath":"executive-orders/2025-03-19-achieving-efficiency-through-state-and-local-preparedness.md"}'),r={name:"executive-orders/2025-03-19-achieving-efficiency-through-state-and-local-preparedness.md"};function s(o,e,l,c,d,h){return a(),t("div",null,e[0]||(e[0]=[n('<h1 id="achieving-efficiency-through-state-and-local-preparedness" tabindex="-1">Achieving Efficiency Through State and Local Preparedness <a class="header-anchor" href="#achieving-efficiency-through-state-and-local-preparedness" aria-label="Permalink to &quot;Achieving Efficiency Through State and Local Preparedness&quot;">​</a></h1><p>Published: Wednesday, March 19, 2025</p><ul><li><p><strong>Authority</strong>: The President asserts authority via the Constitution and U.S. laws to enhance national security and infrastructure resilience through state and local government investment.</p></li><li><p><strong>Objective</strong>: Emphasizes state, local, and individual preparedness as vital to national resilience and effective risk management for threats like cyberattacks and natural disasters.</p></li><li><p><strong>Empowerment</strong>: State and local governments are empowered to make informed infrastructure decisions which lead to better taxpayer outcomes and community resilience.</p></li><li><p><strong>Policy Changes</strong>: Aims to:</p><ul><li>Streamline federal preparedness operations.</li><li>Update government policies for efficiency and clarity.</li><li>Enable state and local governments to better serve citizens.</li></ul></li><li><p><strong>Implementations</strong>:</p><ul><li><strong>National Resilience Strategy</strong>: Due within 90 days, detailing resilience priorities, with a review every 4 years.</li><li><strong>Critical Infrastructure Policy Review</strong>: To be completed within 180 days; it will shift from all-hazards to a risk-informed approach.</li><li><strong>National Continuity Policy Review</strong>: Also within 180 days, to update national continuity capabilities.</li><li><strong>Preparedness and Response Policies Review</strong>: Within 240 days, focusing on Federal responsibility and updating approaches.</li><li><strong>National Risk Register</strong>: Within 240 days to identify and quantify risks to national infrastructure, with a review every 4 years.</li><li><strong>Federal National Functions Constructs</strong>: Proposals for policy changes to better clarify the federal role in preparedness are due within 1 year.</li></ul></li><li><p><strong>Limitations</strong>: The order does not alter existing legal authorities or create new rights enforceable against the U.S. or its agencies. It will be implemented within legal and budgetary constraints.</p></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/achieving-efficiency-through-state-and-local-preparedness/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/achieving-efficiency-through-state-and-local-preparedness/</a></p>',4)]))}const u=i(r,[["render",s]]);export{g as __pageData,u as default};
